SELECT pp.id AS paper_position_id, c.symbol, c.open_time, c.close_time, c.open_price, c.high_price, c.low_price, c.close_price, c.volume, c.closed FROM crypto_ai.candle c JOIN crypto_ai.paper_position pp ON c.symbol = pp.symbol AND c.interval_code = '1m' AND c.open_time BETWEEN pp.opened_at - INTERVAL 10 MINUTE AND pp.closed_at WHERE pp.id IN (182,172,162,158,143,137) ORDER BY pp.id, c.open_time LIMIT 260